create schema private;

grant usage on schema private to authenticated;

create function private.is_board_member(p_board_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
  );
$$;

create function private.can_edit_board(p_board_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
  );
$$;

create function private.board_is_archived(p_board_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.boards b
    where b.id = p_board_id
      and b.is_archived
  );
$$;

alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

create policy boards_select_members
on public.boards
for select
to authenticated
using (private.is_board_member(id));

create policy board_members_select_own
on public.board_members
for select
to authenticated
using (user_id = auth.uid());

create policy cards_select_members
on public.cards
for select
to authenticated
using (private.is_board_member(board_id));

create policy cards_insert_editors
on public.cards
for insert
to authenticated
with check (
  private.is_board_member(board_id)
  and private.can_edit_board(board_id)
  and not private.board_is_archived(board_id)
);

create policy cards_update_editors
on public.cards
for update
to authenticated
using (
  private.is_board_member(board_id)
  and private.can_edit_board(board_id)
  and not private.board_is_archived(board_id)
)
with check (
  private.is_board_member(board_id)
  and private.can_edit_board(board_id)
  and not private.board_is_archived(board_id)
);

create policy cards_delete_editors
on public.cards
for delete
to authenticated
using (
  private.is_board_member(board_id)
  and private.can_edit_board(board_id)
  and not private.board_is_archived(board_id)
);
