alter table public.cards enable row level security;

create function public.is_board_member(p_board_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
  );
$$;

create function public.is_board_editor(p_board_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
  );
$$;

create function public.board_is_archived(p_board_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.boards b
    where b.id = p_board_id
      and b.is_archived = true
  );
$$;

create function public.board_editor_can_access(p_board_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.board_members m
    where m.board_id = p_board_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
  )
  and not public.board_is_archived(p_board_id);
$$;

create policy "boards_select_members"
on public.boards
for select
to authenticated
using (public.is_board_member(id));

create policy "board_members_select_own_board_members"
on public.board_members
for select
to authenticated
using (user_id = auth.uid());

create policy "cards_select_members"
on public.cards
for select
to authenticated
using (
  public.is_board_member(board_id)
  and (public.is_board_editor(board_id) or public.board_is_archived(board_id))
);

create policy "cards_insert_editors"
on public.cards
for insert
to authenticated
with check (
  public.is_board_editor(board_id)
  and not public.board_is_archived(board_id)
  and (
    assignee_id is null
    or public.is_board_editor(
      (select c.board_id from public.cards c where c.id = assignee_id)
    )
  )
);

create policy "cards_update_editors"
on public.cards
for update
to authenticated
using (
  public.is_board_editor(board_id)
  and not public.board_is_archived(board_id)
)
with check (
  public.is_board_editor(board_id)
  and not public.board_is_archived(board_id)
  and (
    assignee_id is null
    or public.is_board_editor(
      (select c.board_id from public.cards c where c.id = assignee_id)
    )
  )
);

create policy "cards_delete_editors"
on public.cards
for delete
to authenticated
using (
  public.is_board_editor(board_id)
  and not public.board_is_archived(board_id)
);

revoke all on public.boards from anon;
revoke all on public.board_members from anon;
revoke all on public.cards from anon;

grant select on public.boards to authenticated;
grant select on public.board_members to authenticated;
grant select, insert, update, delete on public.cards to authenticated;

grant usage, select on sequence public.cards_id_seq to authenticated;

grant all on public.boards to service_role;
grant all on public.board_members to service_role;
grant all on public.cards to service_role;
grant usage, select on sequence public.cards_id_seq to service_role;
