create or replace function public.enforce_post_author()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.author_id is distinct from auth.uid() then
    raise exception 'posts can only be written by their author'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_friendship_ownership()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.requester_id is distinct from auth.uid() then
    raise exception 'friendship requester must be the current user'
      using errcode = '42501';
  end if;

  if new.addressee_id is distinct from auth.uid() then
    raise exception 'friendship addressee must be the current user'
      using errcode = '42501';
  end if;

  if new.status is distinct from 'pending' then
    raise exception 'new friendships must be pending'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_friendship_update()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.requester_id is distinct from old.requester_id
     or new.addressee_id is distinct from old.addressee_id then
    raise exception 'friendship requester and addressee cannot be changed'
      using errcode = '42501';
  end if;

  if old.status = 'pending' and new.status = 'accepted'
     and new.requester_id = new.addressee_id then
    raise exception 'a user cannot accept their own request'
      using errcode = '42501';
  end if;

  if old.status = 'pending' and new.status <> 'accepted' then
    raise exception 'only the addressee of a pending request can accept it'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

