returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if coalesce(
    exists (select 1 from public.requests r where r.id = new.id and public.is_resident(r.unit_id)),
    exists (select 1 from public.requests r join public.building_staff s on s.building_id = u.building_id where r.id = new.id and s.user_id = auth.uid())
  ) then
    if old.created_by is distinct from auth.uid() then
      raise exception 'requests.created_by cannot be changed';
    end if;
    if new.created_by is distinct from old.created_by then
      raise exception 'requests.created_by cannot be changed';
    end if;
    if new.status not in ('open', 'in_progress', 'done') then
      raise exception 'invalid request status';
    end if;
    if old.status = 'done' then
      raise exception 'done requests cannot be updated';
    end if;
    if new.unit_id is distinct from old.unit_id then
      raise exception 'requests.unit_id cannot be changed';
    end if;
    if new.description is distinct from old.description then
      raise exception 'requests.description cannot be changed';
    end if;
    return new;
  end if;
  raise exception 'requests: no access to this request';
end;
