  end if;

  if not exists (select 1 from public.units u where u.id = new.unit_id) then
    raise exception 'Unknown unit';
  end if;

  if not exists (select 1 from public.residents r where r.unit_id = new.unit_id and r.user_id = auth.uid()) then
    raise exception 'You are not a resident of this unit';
  end if;

  if new.status is distinct from 'open' then
    raise exception 'New requests must be open';
  end if;

  return new;
end;
$$;

create or replace function public.request_photos_insert()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.request_id is null or new.path is null then
    raise exception 'request_id and path are required';
  end if;

  if not exists (select 1 from public.requests r where r.id = new.request_id) then
    raise exception 'Unknown request';
  end if;

  if not exists (select 1 from public.request_photos_own_or_staff()) then
    raise exception 'You are not allowed to add photos to this request';
  end if;

  return new;
end;
$$;

