returns trigger
language plpgsql
set search_path = public
as $$
begin
  if public.is_resident(public.units.building_id)
     or public.is_building_staff(public.units.building_id) then
    if tg_op = 'UPDATE'
       and new.id = old.id
       and new.unit_id = old.unit_id
       and new.created_by = old.created_by
       and new.description = old.description
       and new.request_photos = old.request_photos
       and new.status = old.status
    then
      return new;
    end if;
    if tg_op = 'UPDATE'
       and new.id = old.id
       and new.unit_id = old.unit_id
       and new.created_by = old.created_by
       and new.description = old.description
       and new.request_photos = old.request_photos
       and new.status = 'done'
    then
      if public.is_resident(old.unit_id) then
        raise exception 'residents cannot change request status';
      end if;
      if not public.is_building_staff(public.units.building_id) then
        raise exception 'only building staff can change request status';
      end if;
      return new;
    end if;
  end if;
  return new;
end;
