create or replace function public.requests_enforce_policies()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if public.is_resident(new.unit_id) then
    if new.created_by is distinct from auth.uid() then
      raise exception 'request created_by must be the resident';
