    if new.status is distinct from 'open' then
      raise exception 'new requests are always open';
    end if;
  elsif public.is_building_staff(public.requests_buildings()) then
    if new.status is distinct from 'open' then
      raise exception 'new requests are always open';
    end if;
  else
    raise exception 'requests are not allowed';
  end if;
  return new;
end;
$$;

