```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create or replace function public.is_auction_active(p_auction_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.ends_at > now()
  );
$$;

create or replace function public.is_auction_seller(p_auction_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.seller_id = auth.uid()
  );
$$;

create or replace function public.is_bidder_on_auction(p_auction_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.bids b
    where b.auction_id = p_auction_id
      and b.bidder_id = auth.uid()
  );
$$;

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_highest numeric;
  v_min_increment numeric;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  if not exists (select 1 from public.auctions where id = p_auction_id) then
    raise exception 'auction not found';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if v_auction.seller_id = v_user then
    raise exception 'seller cannot bid on own auction';
  end if;

  if not public.is_auction_active(p_auction_id) then
    raise exception 'auction has ended';
  end if;

  if p_amount < v_auction.starting_price then
    raise exception 'bid below starting price';
  end if;

  if v_auction.highest_bid is not null then
    if p_amount < v_auction.highest_bid + v_auction.min_increment then
      raise exception 'bid below minimum increment';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_user, p_amount, now());

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_user
  where id = p_auction_id;

  return p_amount;
end;
$$;

create policy "auctions_select_authenticated"
on public.auctions
for select
to authenticated
using (true);

create policy "bids_select_own_or_seller"
on public.bids
for select
to authenticated
using (bidder_id = auth.uid() or public.is_auction_seller(auction_id));

create policy "bids_insert_authenticated"
on public.bids
for insert
to authenticated
with check (bidder_id = auth.uid());

revoke all on public.auctions from anon;
revoke all on public.bids from anon;

revoke all on public.auctions from authenticated;
revoke all on public.bids from authenticated;

grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;
grant insert on public.bids to authenticated;

grant all on public.auctions to service_role;
