create or replace function public.is_auction_open(p_auction_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.ends_at > now()
  );
$$;

create or replace function public.is_auction_winner(p_auction_id bigint, p_bidder_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.highest_bidder = p_bidder_id
  );
$$;

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_highest numeric := 0;
  v_min_inc numeric := 0;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'bidders cannot bid on their own auctions';
  end if;

  if not public.is_auction_open(p_auction_id) then
    raise exception 'auction has ended';
  end if;

  v_highest := v_auction.highest_bid;
  v_min_inc := v_auction.min_increment;

  if v_highest is null then
    if p_amount < v_auction.starting_price then
      raise exception 'bid is below the starting price';
    end if;
  else
    if p_amount < v_highest + v_min_inc then
      raise exception 'bid is below the minimum increment';
    end if;
  end if;

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_uid
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_uid, p_amount, now());

  return p_amount;
end;
$$;

