create or replace function public.class_spots_enforce_capacity()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_capacity integer;
  v_enrolled integer;
  v_is_instructor boolean;
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.user_id is distinct from auth.uid() then
    raise exception 'class_spots.user_id must be the current user';
  end if;

  if new.status not in ('enrolled', 'waitlisted') then
    raise exception 'class_spots.status must be enrolled or waitlisted';
  end if;

  if new.status = 'enrolled' then
    v_capacity := (select c.capacity from public.classes c where c.id = new.class_id);
    v_enrolled := (select count(*) from public.class_spots s where s.class_id = new.class_id and s.status = 'enrolled');
    if v_enrolled >= v_capacity then
      raise exception 'class is at capacity';
    end if;
  elsif new.status = 'waitlisted' then
    v_capacity := (select c.capacity from public.classes c where c.id = new.class_id);
    v_enrolled := (select count(*) from public.class_spots s where s.class_id = new.class_id and s.status = 'enrolled');
    if v_enrolled < v_capacity then
      raise exception 'class has room; use status = enrolled';
    end if;
  end if;

  if new.id is not null then
    raise exception 'class_spots.id cannot be set on insert';
  end if;

  return new;
end;
$$;

create or replace function public.class_spots_enforce_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_capacity integer;
  v_enrolled integer;
  v_is_instructor boolean;
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.user_id is distinct from auth.uid() then
    raise exception 'class_spots.user_id must be the current user';
  end if;

  if new.status not in ('enrolled', 'waitlisted') then
    raise exception 'class_spots.status must be enrolled or waitlisted';
  end if;

  if new.status = old.status then
    return new;
  end if;

  if old.status = 'enrolled' then
    v_enrolled := (select count(*) from public.class_spots s where s.class_id = old.class_id and s.status = 'enrolled') - 1;
  else
    v_enrolled := (select count(*) from public.class_spots s where s.class_id = old.class_id and s.status = 'enrolled');
  end if;

  if new.status = 'enrolled' then
    v_capacity := (select c.capacity from public.classes c where c.id = old.class_id);
    if v_enrolled >= v_capacity then
      raise exception 'class is at capacity';
    end if;
  elsif new.status = 'waitlisted' then
    v_capacity := (select c.capacity from public.classes c where c.id = old.class_id);
    if v_enrolled >= v_capacity then
      raise exception 'class is at capacity';
    end if;
  end if;

  if new.id is not null then
    raise exception 'class_spots.id cannot be changed';
  end if;

  return new;
end;
$$;

