create or replace function public.class_spots_enforce_role()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_class_id bigint := new.class_id;
  v_status text := new.status;
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  if new.user_id is distinct from v_user then
    raise exception 'class_spots.user_id must be the authenticated user';
  end if;

  if tg_op = 'INSERT' then
    if new.status not in ('enrolled', 'waitlisted') then
      raise exception 'class_spots.status must be enrolled or waitlisted';
    end if;

    if public.class_instructor(v_class_id) then
      if new.status = 'enrolled' then
        raise exception 'instructors cannot be enrolled as students';
      end if;
      return new;
    end if;

    if public.classes_enrollment_capacity(v_class_id) >= (select c.capacity from public.classes c where c.id = v_class_id) then
      new.status := 'waitlisted';
    end if;

    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.status not in ('enrolled', 'waitlisted') then
      raise exception 'class_spots.status must be enrolled or waitlisted';
    end if;

    if new.status = 'enrolled' then
      if public.class_instructor(v_class_id) then
        raise exception 'instructors cannot move spots';
      end if;

      if public.classes_enrollment_capacity(v_class_id) >= (select c.capacity from public.classes c where c.id = v_class_id) then
        raise exception 'class is at capacity';
      end if;
    end if;

    return new;
  end if;

  if tg_op = 'DELETE' then
    if public.class_instructor(v_class_id) then
      return new;
    end if;

    if new.user_id is distinct from v_user then
      raise exception 'class_spots can only be deleted by the member';
    end if;

    return new;
  end if;

  return new;
end;
$$;

