    select c.capacity into v_capacity
      from public.classes c
     where c.id = old.class_id
       and c.instructor_id = auth.uid()
     for update;

    if v_capacity is null then
      raise exception 'class not found or no access';
    end if;

    select count(*) into v_enrolled
      from public.class_spots s
     where s.class_id = old.class_id
       and s.status = 'enrolled'
       and s.user_id <> old.user_id;

    if v_enrolled >= v_capacity then
      raise exception 'class is at capacity, cannot move from waitlisted to enrolled';
    end if;

    return new;
  end if;

  raise exception 'invalid spot status transition';
end;
$$;

