create or replace function public.class_spots_enforce_capacity()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_capacity integer;
  v_enrolled integer;
  v_room boolean;
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if new.id is distinct from old.id then
    raise exception 'class spots are immutable';
  end if;
  if new.status not in ('enrolled', 'waitlisted') then
    raise exception 'invalid spot status';
  end if;
  if new.user_id is distinct from auth.uid() and auth.role() <> 'service_role' then
    raise exception 'only own spots may be changed';
  end if;
  if new.status = 'enrolled' and new.user_id is distinct from old.status then
    select c.capacity into v_capacity
      from public.classes c
     where c.id = new.class_id
       and c.instructor_id = auth.uid()
     for update;
    if v_capacity is null then
      raise exception 'not an instructor';
    end if;
    select count(*) into v_enrolled
      from public.class_spots s
     where s.class_id = new.class_id
       and s.status = 'enrolled';
    v_room := v_enrolled < v_capacity;
    if not v_room then
      raise exception 'no room for enrolled';
    end if;
  end if;
  return new;
end;
$$;

